    // 图片加载完后位置可能漂移，轻量重新定位（不重新注册 observer/timer）
    if (currentScrollTargetId.value) {
      const targetEl = elm.querySelector(
        `[data-id="${currentScrollTargetId.value}"]`,
      );
      if (targetEl) {
        const getOffsetTop = (el, container) => {
          let top = 0,
            curr = el;
          while (curr && curr !== container) {
            top += curr.offsetTop;
            curr = curr.offsetParent;
          }
          return top;
        };
        elm.scrollTo({
          top: Math.max(
            0,
            getOffsetTop(targetEl, elm) - elm.clientHeight * 0.3,
          ),
          behavior: "instant",
        });
      }
    }

    const isNearBottom =
      elm.scrollHeight - elm.scrollTop - elm.clientHeight < 150;
    if (isNearBottom) {
      toButtom();
    }
  }
};

// Lifecycle Hooks
const resizeHandler = ref(null);
const focusHandler = ref(null);

onMounted(() => {
  document.addEventListener("click", () => {
    showMenu.value = false;
    seletedText.value = "";
    seletedImage.value = "";
  });

  if (chatWindow.value) {
    chatWindow.value.addEventListener("scroll", scrollHandler);
    chatWindow.value.addEventListener("mousedown", handleMouseDown);
    chatWindow.value.addEventListener("load", handleImageLoad, true);
  }

  if (window.ResizeObserver && messagesInner.value) {
    resizeObserver = new ResizeObserver((entries) => {
      if (!isObservingResize || !chatWindow.value || autoScroll.value) return;
      for (const entry of entries) {
        if (entry.target === messagesInner.value) {
          const newHeight = messagesInner.value.offsetHeight;
          const diff = newHeight - oldInnerHeight;
          if (diff > 0) {
            chatWindow.value.scrollTop += diff;
            prevScrollTop.value = chatWindow.value.scrollTop;
          }
          oldInnerHeight = newHeight;
        }
      }
    });
    resizeObserver.observe(messagesInner.value);
  }

  autoScroll.value = false;
  if (!preview.value && scroll.value) {
    nextTick(() => {
      if (route.query.scrollTo) {
        performScrollToMessage(route.query.scrollTo);
      } else {
        toButtom();
        setTimeout(() => {
          toButtom();
        }, 100);
      }
    });
  }

  // Sync with socket on mount
  trySync();
  if (
    activeContactor.value?.platform === "channel" &&
    (!activeContactor.value.messageChain ||
      activeContactor.value.messageChain.length === 0)
  ) {
    loadChannelHistory({ limit: 20 });
  }
  if (client.socket) {
    client.socket.on("connect", trySync);
  }
  client.on("socket_ready", (socket) => {
    socket.on("connect", trySync);
    trySync();
  });

  fullScreen.value = client.socket?.fullScreen;

  client.on("plugins_updated", handlePluginsUpdated);
  client.on("scroll_to_message", performScrollToMessage);
  client.on("channel_bots_synced", trySync);
  window.addEventListener("beforeunload", handleBeforeUnload);

  resizeHandler.value = () => {
    isMobileDevice.value = window.innerWidth < 768;
  };
  window.addEventListener("resize", resizeHandler.value);

  focusHandler.value = () => {
    if (dragSelect.isDown) {
      handleMouseUpDrag();
    }
  };
  window.addEventListener("blur", focusHandler.value);

  const element = document.querySelector(".input-bar");
  if (element) {
    const pageHeight = window.innerHeight;
    inputBarTop.value = pageHeight - element.offsetTop;
  }
});

// 使用 Pinia 响应式连接状态触发同步，避免事件覆盖
watch(isConnected, (val) => {
  if (val) {
    trySync();
  }
});

useStatusBarColor("var(--mio-bg-statusbar-friendlist)");

onBeforeUnmount(() => {
  // 在 saveNow 之前先把输入框草稿刷入 contactor，避免 InputEditor.onUnmounted
  // 里的 saveDraft 比 ChatView.saveNow 晚执行导致草稿丢失
  inputEditor.value?.saveDraft();
  if (window.speechSynthesis) {
    window.speechSynthesis.cancel();
  }

  client.off("plugins_updated", handlePluginsUpdated);
  client.off("scroll_to_message", performScrollToMessage);
  client.off("channel_bots_synced", trySync);
  client.off("socket_ready");
  window.removeEventListener("beforeunload", handleBeforeUnload);

  if (client.socket) {
    client.socket.off("connect", trySync);
  }

  // Mark contactor as inactive on leave
  const contactor = contactorsStore.activeContactor;
  if (contactor) {
    contactor.active = false;
  }

  client.saveNow();

  if (chatWindow.value) {
    chatWindow.value.removeEventListener("scroll", scrollHandler);
    chatWindow.value.removeEventListener("mousedown", handleMouseDown);
    chatWindow.value.removeEventListener("load", handleImageLoad, true);
  }

  if (resizeObserver) {
    resizeObserver.disconnect();
    resizeObserver = null;
  }
  if (observeTimer) {
    clearTimeout(observeTimer);
  }

  window.removeEventListener("resize", resizeHandler.value);
  window.removeEventListener("blur", focusHandler.value);
});
</script>

