import { client } from "@/lib/runtime.js";
import { ElMessage } from "element-plus";
import { createRouter, createWebHistory } from "vue-router";
const BlankView = () => import("../views/BlankView.vue");
const ChatView = () => import("../views/ChatView.vue");
const HomeView = () => import("../views/HomeView.vue");
const ProfileView = () => import("../views/ProfileView.vue");
const SettingsView = () => import("../views/SettingsView.vue");
const AuthView = () => import("../views/AuthView.vue");
const EcosystemView = () => import("../views/EcosystemView.vue");

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes: [
    {
      path: "/",
      name: "home",
      component: HomeView,
      meta: { title: "主页" },
      children: [
        {
          path: "/",
          name: "blank",
          component: BlankView,
          meta: { title: "开始对话" },
        },
        {
          path: "/contactors",
          name: "contactors",
          component: BlankView,
          meta: { title: "联系人列表" },
        },
        {
          path: "/chat/:id",
          name: "chat_view",
          component: ChatView,
          meta: { title: "正在聊天" },
        },
        {
          path: "/profile/:id",
          name: "profile_view",
          component: ProfileView,
          meta: { title: "个人信息" },
        },
      ],
    },
    {
      path: "/auth",
      name: "auth",
      component: AuthView,
      meta: { title: "身份验证" },
    },
    {
      path: "/dashboard",
      name: "dashboard",
      component: () => import("../views/DashboardView.vue"),
      meta: { title: "数据审计大盘" },
    },
    {
      path: "/s/:shareId",
      name: "share_link",
      component: BlankView,
      meta: { title: "正在加载分享内容" },
      beforeEnter: async (to, from, next) => {
        // Handle direct share links
        const shareId = to.params.shareId;

        // Ensure client is initialized (wait for it if necessary)
        if (!client.inited) {
          // Pre-init isn't complete, let the App.vue or main.js handle the initialization
          // But since this route is matched, we can just load the contactor
          await client.preInit();
        }

        ElMessage.info("正在获取远程 Agent 信息...");
        const contactorId = await client.loadOriginalContactors(shareId);
        if (contactorId) {
          ElMessage.success("成功加载分享的 Agent");
          next(`/chat/${contactorId}`);
        } else {
          ElMessage.error("分享链接无效或已过期");
          next("/");
        }
      },
    },
    {
      path: "/ecosystem",
      name: "ecosystem",
      component: EcosystemView,
      meta: { title: "生态圈" },
    },
    {
      path: "/open-source",
      redirect: "/ecosystem",
    },
    {
      path: "/settings",
      name: "settings",
      component: SettingsView,
      redirect: "/settings",
      meta: { title: "系统设置" },
      children: [
        {
          path: "",
          name: "settings_overview",
          alias: "overview",
          component: () => import("../views/settings/OverviewView.vue"),
          meta: { title: "设置概览" },
        },
        {
          path: "llm-adapters",
          name: "settings_llm_adapters",
          component: () => import("../views/settings/LLMAdaptersView.vue"),
          meta: { title: "模型适配器" },
        },
        {
          path: "image-adapters",
          name: "settings_image_adapters",
          component: () => import("../views/settings/ImageAdaptersView.vue"),
          meta: { title: "生图服务" },
        },
        {
          path: "search-adapters",
          name: "settings_search_adapters",
          component: () => import("../views/settings/SearchAdaptersView.vue"),
          meta: { title: "搜索服务" },
        },
        {
          path: "vision-adapters",
          name: "settings_vision_adapters",
          component: () => import("../views/settings/VisionAdaptersView.vue"),
          meta: { title: "识图服务" },
        },
        {
          path: "shell-policy",
          name: "settings_shell_policy",
          component: () => import("../views/settings/ShellPermissionsView.vue"),
          meta: { title: "Shell 权限" },
        },
        {
          path: "channels",
          name: "settings_channels",
          component: () => import("../views/settings/ChannelManagerView.vue"),
          meta: { title: "渠道管理" },
        },

        {
          path: "automation",
          name: "settings_automation",
          component: () => import("../views/settings/AutomationView.vue"),
          meta: { title: "自动化任务" },
        },
        {
          path: "push",
          name: "settings_push",
          component: () => import("../views/settings/PushSettingsView.vue"),
          meta: { title: "推送设置" },
        },
        {
          path: "server",
          name: "settings_server",
          component: () => import("../views/settings/ServerConfigView.vue"),
          meta: { title: "服务端配置" },
        },
        {
          path: "web",
          name: "settings_web",
          component: () => import("../views/settings/WebConfigView.vue"),
          meta: { title: "网页端配置" },
        },
        {
          path: "onebot",
          name: "settings_onebot",
          component: () => import("../views/settings/OnebotConfigView.vue"),
          meta: { title: "Onebot 配置" },
        },
        {
          path: "plugins",
          name: "settings_plugins",
          component: () => import("../views/settings/PluginsView.vue"),
          meta: { title: "插件管理" },
        },
        {
          path: "presets",
          name: "settings_presets",
          component: () => import("../views/settings/PresetsView.vue"),
          meta: { title: "预设管理" },
        },
        {
          path: "storage",
          name: "settings_storage",
          component: () => import("../views/settings/StorageConfigView.vue"),
          meta: { title: "存储设置" },
        },
        {
          path: "webhook",
          name: "settings_webhook",
          component: () => import("../views/settings/WebhookConfigView.vue"),
          meta: { title: "Webhook 配置" },
        },
        {
          path: "logs",
          name: "settings_logs",
          component: () => import("../views/settings/LogsView.vue"),
          meta: { title: "系统日志" },
        },
        {
          path: "client",
          name: "settings_client",
          component: () => import("../views/ClientSettingsView.vue"),
          meta: { title: "客户端设置" },
        },
      ],
    },
  ],
});

router.beforeEach(async (to) => {
  const everLogin = client.everLogin();

  // 设置路由特判：无登录或无管理员权限时自动跳转到客户端设置
  if (to.path.startsWith("/settings")) {
    const hasAdminCode = !!localStorage.getItem("admin_code");
    if (!everLogin || !hasAdminCode) {
      if (to.path !== "/settings/client") {
        return { path: "/settings/client" };
      }
    }
    return;
  }

  if (
    // 检查用户是否已登录
    !everLogin &&
    // ❗️ 避免无限重定向
    to.name !== "auth"
  ) {
    console.log(
      `everLogin: ${everLogin} to.name!== auth: ${to.name !== "auth"}`,
    );
    ElMessage.warning("请先登录");
    // 把原本要去的地址 完整的传递给 login?redirect=
    const query = to.path === "/settings" ? null : { redirect: to.fullPath };
    return { name: "auth", query };
  }
});

router.afterEach((to) => {
  const pageTitle = to.meta.title;
  if (pageTitle) {
    document.title = `${pageTitle} - MioChat`;
  } else {
    document.title = "MioChat - 下一代 AI 智能对话平台";
  }
});

export default router;
